class EnvironmentUnavailable(Exception):pass
def ordinary(p,limit=20000):
 s=p.lstat();assert stat.S_ISREG(s.st_mode) and s.st_nlink==1 and s.st_size<limit,'regular bounded single-link file required'
def write_trace(value):
 p=pathlib.Path('native-trace.json')
 if p.exists() or p.is_symlink():ordinary(p,10000000)
 fd,tmp=tempfile.mkstemp(prefix='.018-audit-',dir='.')
 try:
  with os.fdopen(fd,'w') as f:json.dump(value,f,ensure_ascii=False,sort_keys=True)
  if p.exists() or p.is_symlink():ordinary(p,10000000)
  os.replace(tmp,p)
 finally:
  if os.path.exists(tmp):os.unlink(tmp)
def unique(items):
 d={}
 for k,v in items:assert k not in d,'duplicate key';d[k]=v
 return d
def plan():
 material=pathlib.Path('platform-provenance.json');ordinary(material)
 assert hashlib.sha256(material.read_bytes()).hexdigest()==MATERIAL_SHA,'fixed provenance changed'
 p=pathlib.Path('daemon-plan.json');ordinary(p)
 b=p.read_bytes();d=json.loads(b,object_pairs_hook=unique)
 assert set(d)=={'instances','firewall_policy','security_boundary','non_tty_fixture','image_policy'}
 assert d['firewall_policy']=='private_internal_bridges_no_daemon_firewall_writes'
 assert d['security_boundary']=='shared_kernel_not_hostile_tenant' and d['non_tty_fixture'] is True
 assert d['image_policy']=='unchanged_prebuilt_single_uid_root0'
 assert set(d['instances'])=={'a','b'}
 paths=[];bridges=[];subnets=[]
 for name,q in d['instances'].items():
  assert set(q)=={'data','exec','socket','pid','bridge','subnet'}
  for key in ('data','exec','socket','pid'):
   value=q[key];assert isinstance(value,str) and re.fullmatch(name+r'/[a-z][a-z0-9_.-]{0,19}',value)
   assert value.split('/')[1] not in ('config.json','daemon.log');paths.append(value)
  assert re.fullmatch(r's06[a-z0-9-]{1,10}',q['bridge']);bridges.append(q['bridge'])
  assert q['subnet'] in ['10.241.0.0/24','10.242.0.0/24','10.243.0.0/24','10.244.0.0/24'];subnets.append(q['subnet'])
 assert len(set(paths))==8 and len(set(bridges))==len(set(subnets))==2,'instance storage/socket/pid/bridges/address pools must be distinct'
 return d,hashlib.sha256(b).hexdigest()
def main():
 trace={'native_ready':False,'uid':os.getuid(),'wsl_distro':os.environ.get('WSL_DISTRO_NAME'),'cleanup_errors':[]};root=None
 try:
  if os.getuid()!=1000 or os.environ.get('WSL_DISTRO_NAME')!='OpsForge-Validation-20261022':raise EnvironmentUnavailable('fixed validation distro/student UID1000 required')
  t=os.environ.get('OPSFORGE_DAEMON_TOOLS_ROOT','');tool=pathlib.Path(t)
  if not t.startswith('/tmp/opsforge-s06-') or str(tool.resolve())!=str(tool) or tool.stat().st_uid!=1000:raise EnvironmentUnavailable('trusted private restored tools absent')
  for name,expected in EXPECTED_TOOLS.items():
   if hashlib.sha256((tool/name).read_bytes()).hexdigest()!=expected:raise EnvironmentUnavailable('tool hash mismatch: '+name)
  image=tool/'v1.34.1-k3s1.archive.tar'
  if hashlib.sha256(image.read_bytes()).hexdigest()!=IMAGE_SHA:raise EnvironmentUnavailable('unaltered prebuilt image archive absent/changed')
  worker=pathlib.Path(here)/'daemon_worker.py';ordinary(worker,100000)
  assert hashlib.sha256(worker.read_bytes()).hexdigest()==WORKER_SHA,'trusted worker changed'
  probe=subprocess.run(['/usr/bin/unshare','--user','--map-root-user','--','/usr/bin/true'],capture_output=True,timeout=3)
  if probe.returncode:raise EnvironmentUnavailable('nonprivileged user namespaces unavailable')
  trace.update(native_ready=True,tool_hashes=EXPECTED_TOOLS,image_archive_sha256=IMAGE_SHA)
  d,h=plan();trace['learner_input_sha256']=h
  host_net=os.readlink('/proc/self/ns/net');host_user=os.readlink('/proc/self/ns/user');host_forward=pathlib.Path('/proc/sys/net/ipv4/ip_forward').read_text()
  root=pathlib.Path(tempfile.mkdtemp(prefix='opsforge-s06-018-native-'))
  args=['/usr/bin/unshare','--user','--map-root-user','--mount','--net','--pid','--fork','--kill-child=KILL','--mount-proc','--','python3','-B',str(worker),str(root),str(tool),json.dumps(d),host_net,host_user]
  try:
   p=subprocess.run(args,capture_output=True,timeout=95)
   trace['worker_execution']={'argv':args,'exit_code':p.returncode,'stdout':p.stdout.decode(errors='replace'),'stderr':p.stderr.decode(errors='replace')}
   result=json.loads(p.stdout);trace['worker']=result
   if p.returncode or not result['result']['completed']:raise EnvironmentUnavailable('real private daemon execution unavailable: '+str(result['result'].get('error')))
   assert result['all_daemon_processes_exited']
   remaining=[]
   for entry in pathlib.Path('/proc').iterdir():
    if not entry.name.isdigit():continue
    try:
     if os.readlink(entry/'ns/pid')==result['pid_namespace']:remaining.append(entry.name)
    except (FileNotFoundError,PermissionError,ProcessLookupError):pass
   assert not remaining,'private PID namespace still has tasks'
   trace['private_pid_namespace_absent']=True
