   assert root.name.startswith('opsforge-s06-018-native-') and root.stat().st_uid==1000 and str(root.resolve())==str(root)
   shutil.rmtree(root);trace['private_root_removed']=not root.exists()
   assert os.getuid()==1000 and os.readlink('/proc/self/ns/net')==host_net and os.readlink('/proc/self/ns/user')==host_user
   assert pathlib.Path('/proc/sys/net/ipv4/ip_forward').read_text()==host_forward,'caller forwarding changed'
   trace['caller_default_identity_namespaces_forwarding_unchanged']=True
  trace['completed']=True
 except EnvironmentUnavailable as e:
